let audioPrimed = false;
function primeEmbeddedAudio(){
  if (audioPrimed) return;
  audioPrimed = true;
  Object.values(sounds).forEach(a => {
    try {
      a.volume = 0;
      a.play().then(() => {
        a.pause();
        a.currentTime = 0;
        a.volume = 0.72;
      }).catch(() => {
        a.volume = 0.72;
      });
    } catch(e) {
      try { a.volume = 0.72; } catch(_) {}
    }
  });
}
document.addEventListener('visibilitychange', () => { if (!document.hidden) audioPrimed = false; });
window.addEventListener('focus', () => { audioPrimed = false; });

function safePlay(audio){
  if(!soundEnabled || !audio) return;
  try {
    const clone = audio.cloneNode();
    clone.volume = 0.72;
    clone.play().catch(() => {
      try { audio.pause(); audio.currentTime = 0; audio.volume = 0.72; audio.play().catch(() => {}); } catch(_) {}
    });
  } catch(e) {}
}
function playCorrectSound(){ safePlay(sounds.correct); }
function playWrongSound(){ safePlay(sounds.wrong); }
let streakEl;
function updateStreak(val){
  if(!streakEl) streakEl = $("streak");
  streak = val;
  if(streak <= 1){ streakEl.classList.add("hidden"); streakEl.style.color = ""; return; }
  streakEl.classList.remove("hidden");
  streakEl.textContent = "🔥 x" + streak;
  // blanc(0) → jaune(50°) → orange(25°) → rouge(0°) → rouge foncé(350°)
  const t = Math.min(streak / 10, 1); // 0→1 sur 10 streaks
  const h = Math.round(50 - t * 60);  // 50° → -10° (≈350°)
  const s = Math.round(80 + t * 15);  // 80% → 95%
  const l = Math.round(75 - t * 35);  // 75% → 40%
  streakEl.style.color = `hsl(${h < 0 ? h + 360 : h}, ${s}%, ${l}%)`;
  streakEl.classList.toggle("glow", streak >= 8);
}
function animStreak(type){
  if(!streakEl) streakEl = $("streak");
  const cls = type === "pop" ? "streak-pop" : "streak-break";
  streakEl.classList.remove("streak-pop","streak-break");
  void streakEl.offsetWidth;
  streakEl.classList.add(cls);
}
