const audioCtx = new (window.AudioContext||window.webkitAudioContext)();
function getAudioCtx(){ return audioCtx; }
let needsAudioReprime = true;
async function primeWebAudio(){
  if(!needsAudioReprime) return;
  needsAudioReprime = false;
  try {
    const ctx = getAudioCtx();
    if(ctx.state === 'suspended') await ctx.resume();
    // Oscillateur muet de 40ms pour amorcer réellement iOS
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.connect(g); g.connect(ctx.destination);
    g.gain.setValueAtTime(0.0001, ctx.currentTime);
    osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.04);
    // Attendre que l'oscillateur muet soit terminé avant de rendre la main
    await new Promise(r => setTimeout(r, 60));
  } catch(e) {}
}
// Re-marquer le besoin de re-prime à chaque retour de veille / onglet
document.addEventListener('visibilitychange', () => { if(document.visibilityState === 'visible') needsAudioReprime = true; });
window.addEventListener('focus', () => { needsAudioReprime = true; });
window.addEventListener('pageshow', () => { needsAudioReprime = true; });
function playBeep(freq, dur, vol, type='sine'){
  if(!soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = type; osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(vol, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + dur);
    osc.start(ctx.currentTime); osc.stop(ctx.currentTime + dur);
  } catch(e) {}
}
function playTone(freq, dur, vol, attack, type='sine'){
  if(!soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const schedule = () => {
      try {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = type;
        const t = ctx.currentTime + 0.005; // 5ms buffer pour éviter les artefacts de scheduling
        osc.frequency.setValueAtTime(freq, t);
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(vol, t + attack);
        gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
        osc.start(t);
        osc.stop(t + dur + 0.01);
      } catch(e) {}
    };
    if(ctx.state === 'suspended'){ ctx.resume().then(schedule); }
    else { schedule(); }
  } catch(e) {}
}
function playCountdownBeep(step){
  if(step > 0){
    // 3, 2, 1 : ton rond type marimba, fréquence montante
    const freq = 480 + (3 - step) * 60; // 480 → 540 → 600
    playTone(freq, 0.18, 0.38, 0.008);
    playTone(freq * 2, 0.12, 0.09, 0.008); // harmonique légère
  } else {
    // GO : accord ascendant rapide, style lancement
    playTone(600, 0.22, 0.42, 0.006);
    setTimeout(() => playTone(800, 0.22, 0.42, 0.006), 60);
    setTimeout(() => playTone(1000, 0.30, 0.46, 0.006), 130);
  }
}
let lastTickSec = -1;
function playTickSound(sec){
  if(sec === lastTickSec) return;
  lastTickSec = sec;
  // 5→1 : fréquence et présence croissantes, style jeu mobile premium
  const freq = 520 + (5 - sec) * 55;       // 520 → 740 Hz
  const vol  = 0.18 + (5 - sec) * 0.055;   // 0.18 → 0.40
  const dur  = Math.max(0.10, 0.14 - (5 - sec) * 0.01);
  playTone(freq, dur, Math.min(vol, 0.42), 0.006);
  playTone(freq / 2, dur, vol * 0.15, 0.006); // sous-harmonique discrète pour le corps
}

function playRecordSound(){
  if(!soundEnabled) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;
    // Note 1 : Sol5 (780→840 Hz), glide léger, attaque douce
    const o1 = ctx.createOscillator(), g1 = ctx.createGain();
    o1.connect(g1); g1.connect(ctx.destination);
    o1.type = 'sine';
    o1.frequency.setValueAtTime(780, now);
    o1.frequency.linearRampToValueAtTime(840, now + 0.06);
    g1.gain.setValueAtTime(0, now);
    g1.gain.linearRampToValueAtTime(0.40, now + 0.015);
    g1.gain.exponentialRampToValueAtTime(0.001, now + 0.38);
    o1.start(now); o1.stop(now + 0.40);
    // Note 2 : Ré6 (1175 Hz), décalée, harmonique naturelle
    const o2 = ctx.createOscillator(), g2 = ctx.createGain();
    o2.connect(g2); g2.connect(ctx.destination);
    o2.type = 'sine';
    o2.frequency.setValueAtTime(1175, now + 0.09);
    g2.gain.setValueAtTime(0, now + 0.09);
    g2.gain.linearRampToValueAtTime(0.24, now + 0.105);
    g2.gain.exponentialRampToValueAtTime(0.001, now + 0.50);
    o2.start(now + 0.09); o2.stop(now + 0.52);
  } catch(e) {}
}
