function saveGame(){
  localStorage.setItem(STORAGE_KEY, JSON.stringify({ xp, pseudo, soundEnabled, bestScore, statGames, statBestAvgTime, localSession, xpMultiplier }));
  // Clé dédiée pour la session — indépendante du reste du jeu
  if(localSession != null) localStorage.setItem("currentSession", String(localSession));
}
function loadGame(){
  const raw = localStorage.getItem(STORAGE_KEY);
  if(!raw) return;
  try {
    const d = JSON.parse(raw);
    xp = Number(d.xp) || 0;
    pseudo = d.pseudo || "";
    soundEnabled = d.soundEnabled !== false;
    bestScore = Number(d.bestScore) || 0;
    statGames = Number(d.statGames) || 0;
    const _loaded = Number(d.statBestAvgTime);
    statBestAvgTime = (Number.isFinite(_loaded) && _loaded > 0) ? _loaded : null;
    // Priorité à la clé dédiée, fallback sur l'objet principal
    const dedicatedSession = localStorage.getItem("currentSession");
    localSession = dedicatedSession != null ? Number(dedicatedSession)
      : (d.localSession != null ? Number(d.localSession) : null);
    xpMultiplier = (Number(d.xpMultiplier) === 2) ? 2 : 1;
  } catch(e) {}
}

// ── Persistance de la série en cours ──────────────────────────────────────
// Sauvegarde l'état complet de la série dans localStorage.
// Appelé dès le démarrage de la série (pas après la première réponse).
// Cela empêche le reroll : un refresh retrouve exactement les mêmes questions.
function saveSeriesState(){
  try {
    localStorage.setItem(SERIES_STATE_KEY, JSON.stringify({
      pseudo:       pseudo,             // pour invalider si l'élève change
      levelKey:     currentLevelKey,
      questions:    questions,          // tableau complet généré une seule fois
      questionIndex: currentQuestionIndex,
      score:        score,
      seriesXpDelta: _seriesXpDelta,
      seriesTimes:  _seriesTimes,
      supabaseSeriesId: activeSeriesId,   // null si pas encore créé en base
      supabaseSession:  activeSessionForQuiz,
      refreshPenaltyApplied: _refreshPenaltyApplied,
      savedAt:      Date.now()
    }));
  } catch(e) { console.warn("saveSeriesState failed", e); }
}

// Charge l'état persisté d'une série en cours.
// Retourne l'objet ou null si aucune série en cours / élève différent / trop vieux.
function loadSeriesState(){
  try {
    const raw = localStorage.getItem(SERIES_STATE_KEY);
    if(!raw) return null;
    const s = JSON.parse(raw);
    if(!s || !s.questions || !s.levelKey) return null;
    // Invalider si l'élève a changé de pseudo
    if(s.pseudo !== pseudo) return null;
    // Invalider si l'état est trop vieux (> 2 heures) — série abandonnée
    if(Date.now() - (s.savedAt || 0) > 2 * 60 * 60 * 1000) {
      localStorage.removeItem(SERIES_STATE_KEY);
      return null;
    }
    return s;
  } catch(e) { return null; }
}

// Supprime l'état persisté. Appelé à la fin de série ou abandon explicite.
function clearSeriesState(){
  localStorage.removeItem(SERIES_STATE_KEY);
}

