function normalizeQuestion(q) {
  if (!q.subcategory) {
    q.subcategory = q.category || "inconnu";
    console.warn("⚠️ subcategory manquant", { category: q.category, text: q.text });
  }
  if (q.answerDisplay == null) {
    if (q.answer?.kind === "fraction") {
      q.answerDisplay = simplifyFraction(q.answer.num, q.answer.den);
    } else if (q.answer?.value != null) {
      q.answerDisplay = String(q.answer.value);
    } else {
      q.answerDisplay = "";
      console.warn("⚠️ answer manquant", { category: q.category, text: q.text, q });
    }
    console.warn("⚠️ answerDisplay manquant", { category: q.category, text: q.text, fallback: q.answerDisplay });
  }
  return q;
}
function generateQuestions(levelKey){
  const count=LEVELS[levelKey].nbQuestions, out=[];
  for(let i=0;i<count;i++){
    let q;
    if(levelKey==="beginner") q = genBeginnerQuestion();
    else if(levelKey==="intermediate") q = genSmartQuestion();
    else q = genExpertQuestion();
    out.push(normalizeQuestion(q));
  }
  return out;
}

// ─── Système adaptatif de questions ──────────────────────────────────────
// Poids calculés depuis l'historique par sous-catégorie :
//   taux < 50%  → poids 3 (lacune critique)
//   taux < 70%  → poids 2 (lacune modérée)
//   taux ≤ 85%  → poids 1 (correct)
//   taux > 85%  → poids 0.5 (maîtrisé, rare)
let _adaptiveWeights = {};    // { subcategory: weight }
let _lastSubcategory  = null; // anti-répétition

// Générateurs adaptatifs — niveau intermédiaire uniquement
// Timers appliqués via getTimeLimit("intermediate", subcategory) — source : TIMER_CONFIG.
const SUBCATEGORY_GENERATORS = {
  // ── Puissances et racines ─────────────────────────────────────────────────
  carre_parfait:  () => { const a=randomInt(2,15),v=a*a; return {text:`${a}²`,answer:{kind:"number",value:v},answerDisplay:String(v),timeLimit:getTimeLimit("intermediate","carre_parfait"),category:"puissances",subcategory:"carre_parfait"}; },
  racine_carree:  () => { const a=randomInt(2,15); return {text:`√${a*a}`,answer:{kind:"number",value:a},answerDisplay:String(a),timeLimit:getTimeLimit("intermediate","racine_carree"),category:"racines",subcategory:"racine_carree"}; },
  puissance_10:   () => { const sign=Math.random()<0.5?1:-1,n=sign*randomInt(1,6),val=Math.pow(10,n); return {text:`10^${n}`,answer:{kind:"number",value:val},answerDisplay:String(val),timeLimit:getTimeLimit("intermediate","puissance_10"),category:"puissances",subcategory:"puissance_10"}; },
  // ── Fractions ─────────────────────────────────────────────────────────────
  fractions_simplification: () => genIntermediateFractionSimplifyQuestion(), // timer via TIMER_CONFIG dans genIntermediateFractionSimplifyQuestion
  fractions_meme_denominateur: () => {
    const d=randomInt(2,9),n1=randomInt(-9,9)||2,n2=randomInt(-9,9)||-3,add=Math.random()<0.5;
    const num=add?n1+n2:n1-n2;
    return {text:`${n1}/${d} ${add?"+":"-"} ${n2}/${d}`,answer:{kind:"fraction",num,den:d,value:num/d},answerDisplay:simplifyFraction(num,d),timeLimit:getTimeLimit("intermediate","fractions_meme_denominateur"),category:"fractions",subcategory:"fractions_meme_denominateur"};
  },
  // ── Nombres relatifs ──────────────────────────────────────────────────────
  addition_relatifs:       () => { const a=randomInt(-99,99)||1,b=randomInt(-99,99)||1; return {text:`${formatSigned(a)} + ${formatSigned(b)}`,answer:{kind:"number",value:a+b},answerDisplay:String(a+b),timeLimit:getTimeLimit("intermediate","addition_relatifs"),category:"addition",subcategory:"addition_relatifs"}; },
  soustraction_relatifs:   () => { const a=randomInt(-99,99)||1,b=randomInt(-99,99)||1; return {text:`${formatSigned(a)} - ${formatSigned(b)}`,answer:{kind:"number",value:a-b},answerDisplay:String(a-b),timeLimit:getTimeLimit("intermediate","soustraction_relatifs"),category:"soustraction",subcategory:"soustraction_relatifs"}; },
  multiplication_relatifs: () => { const a=randomInt(-9,9)||2,b=randomInt(-9,9)||3; return {text:`${formatSigned(a)} × ${formatSigned(b)}`,answer:{kind:"number",value:a*b},answerDisplay:String(a*b),timeLimit:getTimeLimit("intermediate","multiplication_relatifs"),category:"multiplication",subcategory:"multiplication_relatifs"}; },
  division_relative:       () => { const b=randomChoice([-9,-8,-7,-6,-5,-4,-3,-2,2,3,4,5,6,7,8,9]),v=randomInt(-9,9)||2,a=b*v; return {text:`${formatSigned(a)} ÷ ${formatSigned(b)}`,answer:{kind:"number",value:v},answerDisplay:String(v),timeLimit:getTimeLimit("intermediate","division_relative"),category:"division",subcategory:"division_relative"}; },
};

// SUBCAT_TO_CAT → js/config/categories.js

// Générateur par catégorie (fallback — génère un intermédiaire de la bonne catégorie)
const CATEGORY_GENERATORS = {
  addition:       () => { const q=genIntermediateQuestion(); return q.category==="addition" ? q : SUBCATEGORY_GENERATORS.addition_relatifs(); },
  soustraction:   () => { const q=genIntermediateQuestion(); return q.category==="soustraction" ? q : SUBCATEGORY_GENERATORS.soustraction_relatifs(); },
  multiplication: () => SUBCATEGORY_GENERATORS.multiplication_relatifs(),
  division:       () => SUBCATEGORY_GENERATORS.division_relative(),
  fractions:      () => { const q=genIntermediateQuestion(); return q.category==="fractions" ? q : genIntermediateFractionSimplifyQuestion(); },
  puissances:     () => { const q=genIntermediateQuestion(); return q.category==="puissances" ? q : SUBCATEGORY_GENERATORS.carre_parfait(); },
  racines:        () => SUBCATEGORY_GENERATORS.racine_carree(),
};

// Sélection pondérée dans { clé: poids }
function weightedChoice(weights) {
  const entries = Object.entries(weights).filter(([,w]) => w > 0);
  if (!entries.length) return null;
  const total = entries.reduce((s,[,w]) => s+w, 0);
  let r = Math.random() * total;
  for (const [key, w] of entries) { r -= w; if (r <= 0) return key; }
  return entries[entries.length-1][0];
}

function genSmartQuestion() {
  if (Object.keys(_adaptiveWeights).length > 0 && Math.random() < 0.5) {
    // Anti-répétition : réduire fortement le poids du dernier sous-type joué
    const w = Object.fromEntries(
      Object.entries(_adaptiveWeights).map(([k,v]) => [k, k === _lastSubcategory ? v * 0.15 : v])
    );
    const subcat = weightedChoice(w);
    if (subcat) {
      const gen = SUBCATEGORY_GENERATORS[subcat];
      if (gen) {
        const q = gen();
        _lastSubcategory = q.subcategory;
        console.log(`🎯 Smart [${subcat}] poids=${_adaptiveWeights[subcat]}`);
        return q;
      }
      // Fallback catégorie si pas de générateur dédié
      const cat = SUBCAT_TO_CAT[subcat];
      const catGen = cat && CATEGORY_GENERATORS[cat];
      if (catGen) { const q = catGen(); _lastSubcategory = q.subcategory; return q; }
    }
  }
  const q = genIntermediateQuestion();
  _lastSubcategory = q.subcategory;
  return q;
}

async function getAdaptiveWeights() {
  if (!pseudo || typeof window.saveStudent !== "function") return {};
  try {
    const student = await window.saveStudent(pseudo);
    if (!student) return {};
    const supabase = window.supabase.createClient(
      "https://ypfgfvwpqcamcimppxaf.supabase.co",
      "sb_publishable_j8u0ZTsNqHhSHL9jLmp9Sw_EuKb1ZKi"
    );
    const { data, error } = await supabase
      .from("question_results")
      .select("subcategory, is_correct")
      .eq("student_id", student.id)
      .eq("session", localSession || 1)
      .not("subcategory", "is", null);
    if (error || !data || data.length === 0) return {};
    // Agrégation par sous-catégorie
    const stats = {};
    data.forEach(row => {
      if (!row.subcategory) return;
      if (!stats[row.subcategory]) stats[row.subcategory] = { total: 0, correct: 0 };
      stats[row.subcategory].total++;
      if (row.is_correct) stats[row.subcategory].correct++;
    });
    const weights = {};
    Object.entries(stats).forEach(([subcat, s]) => {
      if (s.total < 3) return; // pas assez de données
      const rate = s.correct / s.total;
      if      (rate < 0.50) weights[subcat] = 3;    // lacune critique
      else if (rate < 0.70) weights[subcat] = 2;    // lacune modérée
      else if (rate <= 0.85) weights[subcat] = 1;   // niveau correct
      else                   weights[subcat] = 0.5; // maîtrisé → apparaît rarement
    });
    const critiques = Object.entries(weights).filter(([,w])=>w===3).map(([k])=>k);
    const moderees  = Object.entries(weights).filter(([,w])=>w===2).map(([k])=>k);
    console.log(`🧠 Adaptatif : ${Object.keys(weights).length} sous-cat analysées`
      + (critiques.length ? ` | 🔴 ${critiques.join(", ")}` : "")
      + (moderees.length  ? ` | 🟡 ${moderees.join(", ")}`  : ""));
    return weights;
  } catch(e) {
    console.error("Erreur getAdaptiveWeights:", e);
    return {};
  }
}

// rankIndexFromXp → js/config/ranks.js

function setQuestionLock(locked){
  questionLocked = locked;
  validateBtnEl.disabled = locked;
  answerInputEl.disabled = locked;
}
function updateProgressBar(){ progressFillEl.style.width = (questions.length ? (currentQuestionIndex/questions.length)*100 : 0) + "%"; }
function updateRankUI(){
  const newIndex = rankIndexFromXp(xp);
  currentRankIndex = newIndex;
  const rank = RANKS[newIndex];

  // Affiche le XP total brut dans le stat box
  if(xpTotalEl) xpTotalEl.textContent = xp;

  // Barre de progression relative au rang actuel
  const isMax = newIndex >= RANKS.length - 1;
  if(isMax){
    xpFillEl.style.width = "100%";
    xpValueEl.textContent = "MAX RANK 👑";
    rankLabelEl.textContent = rank.icon + " " + rank.name;
  } else {
    const minXP = rank.min;
    const maxXP = RANKS[newIndex + 1].min;
    const progress = Math.min(1, Math.max(0, (xp - minXP) / (maxXP - minXP)));
    xpFillEl.style.width = (progress * 100) + "%";
    xpValueEl.textContent = Math.max(0, xp - minXP) + " / " + (maxXP - minXP) + " XP";
    rankLabelEl.textContent = rank.icon + " " + rank.name;
  }
  rankLabelEl.style.color = rank.glow ? rank.color : "";
  rankLabelEl.style.textShadow = rank.glow || "";
  rankLabelEl.style.animation = rank.glow ? "diamant-pulse 2s ease-in-out infinite" : "";

  // Flash XP bar
  xpFillEl.classList.remove("xp-flash");
  xpFillEl.getBoundingClientRect();
  xpFillEl.classList.add("xp-flash");

  document.querySelectorAll(".rank").forEach((el,i) => {
    el.classList.toggle("active", i===newIndex);
    const leftEl = el.querySelector(".rank-left");
    if (leftEl && RANKS[i] && RANKS[i].glow) {
      leftEl.style.color = (i === newIndex) ? RANKS[i].color : "";
      leftEl.style.textShadow = (i === newIndex) ? RANKS[i].glow : "";
    }
  });
}
// ── Bonus multiplicateur x2 ───────────────────────────────────────────────
function renderXpMultBadge(){
  const badge = document.getElementById("xpMultBadge");
  if(xpMultiplier === 2){
    document.body.classList.add("bonus-x2");
    if(badge) badge.classList.remove("hidden");
  } else {
    document.body.classList.remove("bonus-x2");
    if(badge) badge.classList.add("hidden");
  }
}
function activateXpBonus(){
  if(xpMultiplier === 2) return;
  xpMultiplier = 2;
  saveGame();
  renderXpMultBadge();
}
let bonusLost = false;
function breakXpBonus(){
  if(xpMultiplier !== 2) return;
  xpMultiplier = 1;
  saveGame();
  renderXpMultBadge();
  try { playRankDownSound(); } catch(e) {}
  const el = document.getElementById("bonusLost");
  if(el){
    bonusLost = true;
    el.classList.remove("hidden");
    // reflow pour relancer l'animation si breakXpBonus enchaîne
    el.style.animation = "none"; el.getBoundingClientRect(); el.style.animation = "";
    clearTimeout(el._t);
    el._t = setTimeout(() => {
      bonusLost = false;
      el.classList.add("hidden");
    }, 2200);
  }
}

function applyXp(delta){
  try {
    const previousIndex = rankIndexFromXp(xp);
    const nextXp = Math.max(0, xp + delta);
    const nextIndex = rankIndexFromXp(nextXp);
    xp = nextXp;
    updateRankUI();
    saveGame();
    updateLevelButtons();   // verrouillage en live : dès que xp change, boutons mis à jour
    if(nextIndex > previousIndex) {
      playRankUpSound();
      showRankOverlay(RANKS[nextIndex], false);
    } else if(nextIndex < previousIndex) {
      playRankDownSound();
      showRankOverlay(RANKS[nextIndex], true);
    }
  } catch(e) {
    console.error("applyXp error", e);
  }
}
function startTimer(){
  clearInterval(timerInterval);
  timerEl.classList.remove("timer-critical");
  lastTickSec = -1;
  const startedAt = Date.now();
  timeLeft = currentTimeLimit;
  timerEl.textContent = timeLeft;
  timerEl.style.color = "white";
  timerInterval = setInterval(() => {
    const elapsed = Math.floor((Date.now() - startedAt) / 1000);
    timeLeft = Math.max(0, currentTimeLimit - elapsed);
    timerEl.textContent = timeLeft;
    if(timeLeft <= 5) {
      timerEl.style.color = "#f87171";
      if(!timerEl.classList.contains("timer-critical")) timerEl.classList.add("timer-critical");
      if(timeLeft > 0) playTickSound(timeLeft);
    }
    if(timeLeft <= 0){ clearInterval(timerInterval); timerInterval = null; handleTimeout(); }
  }, 200); // haute fréquence pour précision, pas de dérive
}
function showQuestion(){
  if(currentQuestionIndex >= questions.length) return endQuiz();
  const q = questions[currentQuestionIndex];
  currentAnswer = q.answer.value;
  currentAnswerDisplay = valueToDisplay(q.answer);
  currentTimeLimit = q.timeLimit || 15;
  selectedLevelEl.textContent = "Niveau : " + currentLevel.name;
  questionEl.textContent = q.text + " = ?";
  helperEl.textContent = `Question ${currentQuestionIndex+1} sur ${questions.length} • Temps : ${currentTimeLimit}s${q.hint ? ' • ' + q.hint : ''}`;
  questionCountEl.textContent = `${currentQuestionIndex+1}/${questions.length}`;
  scoreEl.textContent = score;
  answerInputEl.value = "";
  feedbackEl.className = "feedback";
  feedbackEl.textContent = "";
  resultEl.textContent = "";
  updateProgressBar();
  _questionStartTime = Date.now();
  setQuestionLock(false);
  // Animation d'entrée de la carte question
  const qCard = document.querySelector(".question-card");
  if(qCard){ qCard.classList.remove("question-enter","flash-good","flash-bad","shake"); qCard.getBoundingClientRect(); qCard.classList.add("question-enter"); }
  // Focus uniquement sur desktop — sur touch, focus() déclenche le clavier
  // natif iOS même avec inputmode="none" sur certaines versions Safari.
  if (!isTouchDevice) {
    setTimeout(() => { try { answerInputEl.focus(); } catch(e){} }, 80);
  }
  startTimer();
}
function triggerFlash(type){
  const qCard = document.querySelector(".question-card");
  if(!qCard) return;
  // Force reflow en retirant TOUTES les classes d'animation d'abord
  qCard.classList.remove("flash-good","flash-bad","shake");
  // Lecture forcée du layout pour reset l'animation
  qCard.getBoundingClientRect();
  if(type === "good"){
    qCard.classList.add("flash-good");
  } else {
    qCard.classList.add("flash-bad","shake");
  }
}
function triggerFeedbackAnim(){
  feedbackEl.classList.remove("feedback-show");
  feedbackEl.getBoundingClientRect();
  feedbackEl.classList.add("feedback-show");
}
function showCorrectionAndContinue(){
  clearInterval(timerInterval); timerInterval = null;
  timerEl.classList.remove("timer-critical");
  feedbackEl.className = "feedback correction";
  feedbackEl.textContent = "Bonne réponse : " + currentAnswerDisplay;
  triggerFeedbackAnim();
  triggerFlash("bad");
  setTimeout(() => {
    currentQuestionIndex++;
    showQuestion();
  }, 1400);
}
function handleTimeout(){
  if(questionLocked) return;
  setQuestionLock(true);
  clearInterval(timerInterval); timerInterval = null;
  timerEl.classList.remove("timer-critical");
  const _rt = _questionStartTime ? (Date.now() - _questionStartTime) / 1000 : currentTimeLimit;
  if (!questions[currentQuestionIndex]) {
    console.error("❌ currentQuestionIndex hors limites", { index: currentQuestionIndex, length: questions.length, questions });
    return;
  }
  let _q = normalizeQuestion(questions[currentQuestionIndex]);
  const _cat = _q.category ?? null;
  const _subcat = _q.subcategory ?? null;
  const _qtext = _q.text ?? null;
  const _expected = _q.answerDisplay ?? null;
  console.log("QUESTION AVANT SAVE (timeout) =", _q);
  console.log("PAYLOAD SAVE =", { questionText: _qtext, expectedAnswer: _expected, answerDisplay: _expected, subcategory: _subcat, userAnswer: "", isCorrect: false });
  if(_questionStartTime) _seriesTimes.push(_rt);
  breakXpBonus();
  const _timeoutXpDelta = currentLevel.timeout > 0 ? -currentLevel.timeout : 0;
  _seriesXpDelta += _timeoutXpDelta;
  _seriesQuestionResults.push({ subcategory: _subcat, category: _cat, isCorrect: false, responseTime: _rt });
  saveQuestionResult(false, _rt, _cat, _timeoutXpDelta, _subcat, _qtext, _expected, "");
  if(currentLevel.timeout>0) applyXp(-currentLevel.timeout);
  updateSeriesProgress();
  playWrongSound();
  animStreak("break"); updateStreak(0);
  saveSeriesState(); // fige l'état après timeout
  showCorrectionAndContinue();
}
function checkAnswer(){
  if(!quizStarted || questionLocked) return;
  const input = answerInputEl.value.trim();
  if(!input){
    feedbackEl.className = "feedback";
    feedbackEl.textContent = "⚠️ Entre une réponse.";
    triggerFeedbackAnim();
    return;
  }
  setQuestionLock(true);
  clearInterval(timerInterval); timerInterval = null;
  timerEl.classList.remove("timer-critical");
  const _rt = _questionStartTime ? (Date.now() - _questionStartTime) / 1000 : null;
  if (!questions[currentQuestionIndex]) {
    console.error("❌ currentQuestionIndex hors limites", { index: currentQuestionIndex, length: questions.length, questions });
    return;
  }
  let _q = normalizeQuestion(questions[currentQuestionIndex]);
  const _cat = _q.category ?? null;
  const _subcat = _q.subcategory ?? null;
  const _qtext = _q.text ?? null;
  const _expected = _q.answerDisplay ?? null;
  const _isCorrect = areEquivalent(input, currentAnswer);
  console.log("QUESTION AVANT SAVE =", _q);
  console.log("PAYLOAD SAVE =", { questionText: _qtext, expectedAnswer: _expected, answerDisplay: _expected, subcategory: _subcat, userAnswer: input, isCorrect: _isCorrect });
  if(_questionStartTime) _seriesTimes.push(_rt);
  if(_isCorrect){
    const _gain = currentLevel.gain * xpMultiplier;
    _seriesXpDelta += _gain;
    _seriesQuestionResults.push({ subcategory: _subcat, category: _cat, isCorrect: true, responseTime: _rt });
    saveQuestionResult(true, _rt, _cat, _gain, _subcat, _qtext, _expected, input);
    score++;
    applyXp(_gain);
    updateSeriesProgress();
    playCorrectSound();
    feedbackEl.className = "feedback feedback-good";
    feedbackEl.textContent = "✅ Bonne réponse ! +" + _gain + " XP" + (xpMultiplier === 2 ? " 🔥 x2" : "");
    triggerFeedbackAnim();
    triggerFlash("good");
    updateStreak(streak + 1); animStreak("pop");
    scoreEl.textContent = score;
    // Micro-animation score
    scoreEl.classList.remove("score-pop"); scoreEl.getBoundingClientRect(); scoreEl.classList.add("score-pop");
    setTimeout(() => {
      currentQuestionIndex++;
      saveSeriesState(); // fige le nouvel index — un refresh reprend à la bonne question
      showQuestion();
    }, 700);
  } else {
    breakXpBonus();
    const _wrongXpDelta = currentLevel.wrong > 0 ? -currentLevel.wrong : 0;
    _seriesXpDelta += _wrongXpDelta;
    _seriesQuestionResults.push({ subcategory: _subcat, category: _cat, isCorrect: false, responseTime: _rt });
    saveQuestionResult(false, _rt, _cat, _wrongXpDelta, _subcat, _qtext, _expected, input);
    if(currentLevel.wrong > 0) applyXp(-currentLevel.wrong);
    updateSeriesProgress();
    playWrongSound();
    scoreEl.textContent = score;
    animStreak("break"); updateStreak(0);
    saveSeriesState(); // fige l'état après mauvaise réponse
    showCorrectionAndContinue();
  }
}
function buildCoachingFeedback(pct, avgTime) {
  const SUBCAT_LABELS = {
    // ── Débutant ─────────────────────────────────────────────────────────
    addition_simple:                    "Addition simple",
    addition_retenue:                   "Addition avec retenue",
    soustraction_simple:                "Soustraction simple",
    soustraction_retenue:               "Soustraction avec retenue",
    multiplication_simple:              "Tables de multiplication",
    division_simple:                    "Division simple",
    // ── Intermédiaire ─────────────────────────────────────────────────────
    carre_parfait:                      "Carrés parfaits (2²–15²)",
    racine_carree:                      "Racines carrées (√4–√225)",
    puissance_10:                       "Puissances de 10 (10^±1–10^±6)",
    fractions_simplification:           "Simplifier des fractions",
    fractions_meme_denominateur:        "Fractions (même dénominateur)",
    addition_relatifs:                  "Addition de relatifs",
    soustraction_relatifs:              "Soustraction de relatifs",
    multiplication_relatifs:            "Multiplication de relatifs",
    division_relative:                  "Division de relatifs",
    // ── Expert ────────────────────────────────────────────────────────────
    addition_3chiffres:                 "Addition (3 chiffres)",
    soustraction_3chiffres:             "Soustraction (3 chiffres)",
    puissance_cube:                     "Puissances de 3 (2³–10³)",
    reduction_termes:                   "Réduction de termes",
    distributivite_simple:              "Distributivité simple",
    fractions_denominateurs_differents: "Fractions (dénominateurs différents)",
    pourcentage_entier:                 "Pourcentages",
    // ── Historique (données existantes avant refonte) ─────────────────────
    addition_grands_nombres:            "Addition (grands nombres)",
    soustraction_grands_nombres:        "Soustraction (grands nombres)",
    multiplication_grands_nombres:      "Multiplication",
    division_euclidienne:               "Division",
    puissance_carre:                    "Puissances (carré)",
    fractions_multiplication:           "Fractions (×)",
    fractions_division:                 "Fractions (÷)",
  };

  // Agrégation par sous-catégorie pour cette série
  const agg = {};
  _seriesQuestionResults.forEach(r => {
    if (!r.subcategory) return;
    if (!agg[r.subcategory]) agg[r.subcategory] = { correct: 0, total: 0 };
    agg[r.subcategory].total++;
    if (r.isCorrect) agg[r.subcategory].correct++;
  });

  // Sous-catégorie la plus faible (< 60%, ≥ 2 questions)
  const weakest = Object.entries(agg)
    .filter(([, s]) => s.total >= 2 && s.correct / s.total < 0.60)
    .sort((a, b) => (a[1].correct / a[1].total) - (b[1].correct / b[1].total))[0] || null;

  // 1) Phrase résultat — interprétation, pas score brut
  let emoji, msg;
  if      (pct >= 90) { emoji = "🏆"; msg = "Excellente série, tu maîtrises ce niveau."; }
  else if (pct >= 70) { emoji = "🔥"; msg = "Belle performance, tu es solide."; }
  else if (pct >= 50) { emoji = "⚡"; msg = "Bon rythme, tu es sur la bonne voie."; }
  else if (pct >= 30) { emoji = "💪"; msg = "Série courageuse, tu progresses."; }
  else                { emoji = "🎯"; msg = "Chaque essai te fait avancer, continue."; }

  // 2) 1–2 infos clés (réussite + temps moyen qualifié)
  const infos = [`Réussite : <strong>${pct}%</strong>`];
  if (avgTime && avgTime > 0) {
    const t = avgTime.toFixed(1);
    const tLabel = avgTime <= 4 ? "rapide" : avgTime <= 8 ? "bon rythme" : "posé";
    const tColor = avgTime <= 4 ? "#4ade80" : avgTime <= 8 ? "#fbbf24" : "#93c5fd";
    infos.push(`Temps moyen : <strong style="color:${tColor}">${t}s</strong> (${tLabel})`);
  }
  const infosHtml = `<div class="coaching-time">${infos.join(" &nbsp;•&nbsp; ")}</div>`;

  // 3) Un seul point à améliorer
  let improvementHtml = "";
  let weakLabel = null;
  if (weakest) {
    weakLabel = SUBCAT_LABELS[weakest[0]] || weakest[0];
    const rate = Math.round(weakest[1].correct / weakest[1].total * 100);
    improvementHtml = `<div class="coaching-section" style="margin-top:12px">
      <div class="coaching-section-title">📌 À travailler</div>
      <div class="coaching-pills"><span class="coaching-pill weak">${weakLabel} &middot; ${rate}%</span></div>
    </div>`;
  } else if (pct < 100 && avgTime && avgTime > 8) {
    improvementHtml = `<div class="coaching-section" style="margin-top:12px">
      <div class="coaching-section-title">📌 À travailler</div>
      <div class="coaching-pills"><span class="coaching-pill weak">Un peu plus de vitesse</span></div>
    </div>`;
  } else if (pct < 100) {
    improvementHtml = `<div class="coaching-section" style="margin-top:12px">
      <div class="coaching-section-title">📌 À travailler</div>
      <div class="coaching-pills"><span class="coaching-pill weak">Viser le score parfait</span></div>
    </div>`;
  }

  // 4) Une action concrète (adaptée au niveau courant)
  const isExpert = currentLevelKey === "expert";
  let action;
  if (isExpert) {
    if (pct === 100)      action = (avgTime && avgTime > 4) ? `Optimise ton temps de réponse.` : `Maintiens ce niveau d'excellence.`;
    else if (pct >= 80)   action = `Vise le score parfait.`;
    else                  action = `Reviens en intermédiaire pour consolider.`;
  }
  else if (weakest)                      action = `Rejoue une série et concentre-toi sur <strong>${weakLabel}</strong>.`;
  else if (pct < 70)                     action = `Rejoue ce niveau pour consolider tes acquis.`;
  else if (avgTime && avgTime > 8)       action = `Tente une nouvelle série en cherchant un peu plus de rythme.`;
  else if (pct >= 90)                    action = `Passe au niveau supérieur pour relever le défi.`;
  else                                   action = `Enchaîne une nouvelle série pour progresser.`;

  return `<div class="coaching-block">
    <div class="coaching-header"><span class="coaching-emoji">${emoji}</span><span>${msg}</span></div>
    ${infosHtml}
    ${improvementHtml}
    <div class="coaching-objective">🎯 ${action}</div>
  </div>`;
}

function endQuiz(){
  quizStarted = false;
  clearInterval(timerInterval); timerInterval = null;
  timerEl.classList.remove("timer-critical");
  timerEl.style.color = "white";
  timerEl.textContent = "0";
  progressFillEl.style.width = "100%";
  const total = questions.length;
  const pct = Math.round((score / total) * 100);
  bestScore = Math.max(bestScore, score);
  statGames++;
  let avgTime = null;
  if(_seriesTimes.length > 0){
    avgTime = _seriesTimes.reduce((a,b) => a+b, 0) / _seriesTimes.length;
    if(Number.isFinite(avgTime) && avgTime > 0){
      const prevBest = (statBestAvgTime !== null && Number.isFinite(statBestAvgTime) && statBestAvgTime > 0) ? statBestAvgTime : null;
      const newBest = prevBest === null ? avgTime : Math.min(prevBest, avgTime);
      const isRecord = prevBest !== null && newBest < prevBest;
      statBestAvgTime = newBest;
      if(isRecord){ playRecordSound(); showRecordAnim(avgTime); }
    }
  }
  clearSeriesState(); // série terminée — plus de reprise possible
  renderStats(avgTime);
  saveGame();
  updateLevelButtons();
  questionEl.textContent = "Fin du défi";
  helperEl.textContent = "Tu peux relancer une partie ou changer de niveau.";
  const _bonusWasActive = xpMultiplier === 2;
  if(pct === 100) activateXpBonus();
  feedbackEl.className = pct===100 ? "feedback feedback-bonus" : "feedback";
  let _perfectMsg;
  if(pct === 100){
    _perfectMsg = _bonusWasActive
      ? "🔥 Incroyable ! Tu conserves ton <strong>Bonus x2</strong>."
      : "🏆 Parfait ! Tes points comptent <strong>double</strong> à partir de maintenant.";
  }
  feedbackEl.innerHTML = pct===100 ? _perfectMsg : pct>=70 ? "🔥 Très solide !" : pct>=40 ? "⚡ Pas mal, continue !" : "💪 Rejoue pour progresser.";
  triggerFeedbackAnim();
  // ── Résumé XP détaillé (transparent si pénalité refresh présente) ──────────
  const xpNet = _seriesXpDelta;
  const xpFromQuestions = _refreshPenaltyApplied ? xpNet + 10 : xpNet;
  const fmtXp = v => v >= 0 ? `+${v}` : `${v}`;
  const colorXp = v => v >= 0 ? "#4ade80" : "#f87171";
  let xpLine;
  if (_refreshPenaltyApplied) {
    xpLine = `XP questions : <span style="color:#4ade80">${fmtXp(xpFromQuestions)}</span>`
           + ` &nbsp;−&nbsp; pénalité refresh : <span style="color:#f87171">−10</span>`
           + ` &nbsp;=&nbsp; XP net : <span style="color:${colorXp(xpNet)}">${fmtXp(xpNet)}</span>`;
  } else {
    xpLine = `XP net : <span style="color:${colorXp(xpNet)}">${fmtXp(xpNet)}</span>`;
  }
  resultEl.innerHTML = `
    <div style="font-size:16px;font-weight:700;color:var(--muted);margin-bottom:4px">
      Score final : ${score}/${total} &nbsp;•&nbsp; Meilleur : ${bestScore}
    </div>
    <div style="font-size:14px;font-weight:700">${xpLine}</div>
    ${buildCoachingFeedback(pct, avgTime)}
  `;
  answerInputEl.classList.add("hidden");
  validateBtnEl.classList.add("hidden");
  restartBtnEl.classList.remove("hidden");
  $("keypad").classList.add("hidden");
  document.querySelector(".main-card")?.classList.remove("keypad-open");
  showPenaltyBanner(false); // s'assurer que le banner est caché en fin de série
  setQuestionLock(true);
  
  // Sauvegarde automatique de la série dans Supabase
  if (!hasSavedSeries && pseudo) {
    hasSavedSeries = true;
    const xpGained = _seriesXpDelta;
    if (activeSeriesId) {
      // Nouveau système : mettre à jour la ligne créée au début
      (async () => {
        try {
          const student = await window.saveStudent(pseudo);
          if (!student) return;
          await _qClient.from("series_results").update({
            score,
            avg_time: avgTime,
            xp_gained: xpGained,
            streak_max: streak
          }).eq("id", activeSeriesId);
          // Mettre à jour students.xp_total avec le vrai delta (pas score×gain)
          const updatedStudent = {
            xp_total: (student.xp_total || 0) + xpGained,
            best_score: Math.max(student.best_score || 0, score || 0),
            best_avg_time: student.best_avg_time == null ? avgTime : (avgTime ? Math.min(student.best_avg_time, avgTime) : student.best_avg_time),
            games_played: (student.games_played || 0) + 1,
            updated_at: new Date().toISOString()
          };
          await _qClient.from("students").update(updatedStudent).eq("id", student.id);
          console.log("📤 Série mise à jour (id:", activeSeriesId, ") — xp_gained:", xpGained, "(Σ xp_delta)");
        } catch(e) {
          console.error("❌ Erreur mise à jour série:", e);
        }
      })();
    } else if (typeof window.saveSeriesResult === "function") {
      // Fallback ancien système (pas de activeSeriesId)
      window.saveSeriesResult({
        pseudo, level: currentLevelKey, score, avgTime, xpGained, streakMax: streak
      }).then(r => r && console.log("📤 Série sauvegardée (fallback):", r))
        .catch(e => console.error("❌ Erreur sauvegarde série:", e));
    }
  }
}
async function startQuiz(){
  // ── Reprise après refresh ────────────────────────────────────────────────
  // Si une série en cours existe pour le même élève et niveau, on la reprend.
  // Cela empêche le reroll : les questions sont figées dès le démarrage.
  const savedState = loadSeriesState();
  const isResume = savedState && savedState.levelKey === currentLevelKey;

  if(isResume){
    // Restaurer l'état exact d'avant le refresh
    questions          = savedState.questions;
    currentQuestionIndex = savedState.questionIndex;
    score              = savedState.score;
    _seriesXpDelta     = savedState.seriesXpDelta || 0;
    _seriesTimes       = savedState.seriesTimes   || [];
    activeSeriesId     = savedState.supabaseSeriesId || null;
    activeSessionForQuiz = savedState.supabaseSession || null;
    hasSavedSeries     = false;
    _refreshPenaltyApplied = savedState.refreshPenaltyApplied || false;
    // Pénalité due si elle n'a pas encore été enregistrée en base pour cette reprise
    _refreshPenaltyPending = !_refreshPenaltyApplied;
    console.log("▶️ Reprise série (anti-reroll) — question", currentQuestionIndex + 1, "/", questions.length,
      _refreshPenaltyPending ? "— pénalité refresh -10 XP en attente" : "— pénalité déjà appliquée");
  } else {
    // Nouvelle série : générer les questions et effacer tout état précédent
    questions          = generateQuestions(currentLevelKey);
    currentQuestionIndex = 0;
    score              = 0;
    _seriesTimes       = [];
    _seriesXpDelta     = 0;
    _seriesQuestionResults = [];
    hasSavedSeries     = false;
    activeSeriesId     = null;
    activeSessionForQuiz = null;
    _refreshPenaltyApplied = false;
    _refreshPenaltyPending = false;
    clearSeriesState();
  }

  console.log("[QUIZ] startQuiz entered");

  // Persister l'état immédiatement — les questions sont maintenant figées
  // Un refresh retrouvera exactement cette série, pas une nouvelle
  saveSeriesState();

  // Lancer l'UI immédiatement sans attendre Supabase
  updateStreak(0);
  quizStarted=true;
  scoreEl.textContent= String(score);
  questionCountEl.textContent=`${currentQuestionIndex}/${questions.length}`;
  feedbackEl.className="feedback";
  feedbackEl.textContent="";
  showPenaltyBanner(_refreshPenaltyPending);
  resultEl.textContent="";
  answerInputEl.classList.remove("hidden");
  validateBtnEl.classList.remove("hidden");
  restartBtnEl.classList.add("hidden");
  $("keypad").classList.remove("hidden");
  if (isTouchDevice) {
    // Mesure la vraie hauteur du keypad pour ajuster le padding-bottom de main-card
    // (évite une valeur fixe arbitraire qui serait trop grande ou trop petite)
    requestAnimationFrame(() => {
      const kp = $("keypad");
      if (kp) {
        const h = kp.offsetHeight;
        document.documentElement.style.setProperty("--keypad-h", h + "px");
      }
      document.querySelector(".main-card")?.classList.add("keypad-open");
    });
  }
  console.log("[QUIZ] showQuestion called");
  showQuestion();

  // Récupérer la session Supabase en arrière-plan — n'empêche pas la série
  if(pseudo && typeof window.saveStudent === "function"){
    console.log("[QUIZ] saveStudent start");
    window.saveStudent(pseudo).then(student => {
      console.log("[QUIZ] saveStudent done", student ? "ok" : "null");
      if(student){ activeSessionForQuiz = student.session || 1; }
      else { console.error("❌ Impossible de récupérer le student"); }
    }).catch(e => {
      console.error("Erreur init partie:", e);
    });
  }
}
async function selectLevel(levelKey){
  if(levelKey === "beginner" && xp >= 700){
    console.log("🚫 Niveau Débutant bloqué (XP:", xp, ")");
    return;
  }
  if(levelKey === "intermediate" && xp >= 1500){
    console.log("🚫 Niveau Intermédiaire bloqué (XP:", xp, ")");
    return;
  }
  // Nettoyage : effacer l'état persisté seulement si c'est un niveau différent
  // ou si aucune série en cours pour ce niveau+pseudo.
  // Si l'élève reprend le même niveau (ex: refresh), on préserve l'état
  // pour que startQuiz puisse reprendre la même série (anti-reroll).
  const existingState = loadSeriesState();
  const isResumable = existingState && existingState.levelKey === levelKey;
  if(!isResumable){
    clearSeriesState();
  }
  clearInterval(timerInterval); timerInterval = null;
  timerEl.classList.remove("timer-critical");
  quizStarted = false;
  currentLevelKey = levelKey;
  currentLevel = LEVELS[levelKey];
  updateActiveButton(levelKey);
  // Charger les poids adaptatifs silencieusement avant de lancer
  if(levelKey === "intermediate"){
    _adaptiveWeights = await getAdaptiveWeights();
  } else {
    _adaptiveWeights = {};
  }
  _lastSubcategory = null;
  showCountdown(() => startQuiz());
}

