// authUser (optionnel) : objet Supabase Auth user, passé après login.
// Résolution du pseudo par triple fallback (ordre de priorité) :
//   (a) user_metadata.pseudo   — stocké à l'inscription
//   (b) lm_uid_<userId>        — mapping uid→pseudo appris à la 1ère connexion réussie
//   (c) pseudo local            — valeur en mémoire (utile hors auth)
// Le mapping (b) est écrit dès qu'un élève est trouvé en DB. Il survit aux reset
// de localStorage (unlockPseudo ne le supprime pas) ce qui permet de restaurer
// les comptes créés avant que user_metadata.pseudo soit implémenté.
async function syncStudentFromSupabase(authUser = null) {
  // ── Résolution du pseudo ──────────────────────────────────────────────────
  const metaPseudo = authUser?.user_metadata?.pseudo || null;
  const mapPseudo  = authUser ? localStorage.getItem("lm_uid_" + authUser.id) : null;
  const pseudoRaw  = metaPseudo || mapPseudo || pseudo;
  const pseudoToUse = pseudoRaw ? (window.normalizePseudo ? window.normalizePseudo(pseudoRaw) : String(pseudoRaw).trim().toLowerCase()) : "";

  console.log("[sync] ▶ syncStudentFromSupabase");
  console.log("[sync]   authUser:", authUser ? authUser.email : "null");
  console.log("[sync]   (a) user_metadata.pseudo:", JSON.stringify(metaPseudo));
  console.log("[sync]   (b) lm_uid_map:", JSON.stringify(mapPseudo));
  console.log("[sync]   (c) pseudo local:", JSON.stringify(pseudo));
  console.log("[sync]   → pseudoToUse:", JSON.stringify(pseudoToUse));

  if (!pseudoToUse) {
    console.warn("[sync] ⚠️ Aucun pseudo disponible depuis aucune source → restauration impossible");
    return;
  }

  try {
    console.log("[SYNC] start — pseudo:", pseudoToUse);

    const queryPromise = _qClient
      .from("students")
      .select("*")
      .ilike("pseudo", pseudoToUse)
      .maybeSingle();
    const timeoutPromise = new Promise(resolve =>
      setTimeout(() => resolve({ data: null, error: { message: "timeout" } }), 2000)
    );
    let { data: existing, error: qErr } = await Promise.race([queryPromise, timeoutPromise]);

    if (qErr?.message === "timeout") {
      console.warn("[SYNC] students query timeout — restauration abandonnée silencieusement");
      console.log("[SYNC] hydration skipped");
      return;
    }

    if (qErr) {
      console.warn("[SYNC] retry — première tentative échouée:", qErr.message);
      await new Promise(r => setTimeout(r, 500));
      ({ data: existing, error: qErr } = await _qClient
        .from("students")
        .select("*")
        .ilike("pseudo", pseudoToUse)
        .maybeSingle());
    }

    if (qErr) {
      console.error("[sync] ❌ Erreur requête Supabase après retry:", qErr);
      return;
    }
    console.log("[SYNC] success — résultat:", existing ? `trouvé (${existing.pseudo})` : "absent");
    console.log("[sync] Résultat DB:", existing
      ? `✅ trouvé — id: ${existing.id} | pseudo: ${existing.pseudo} | session: ${existing.session}`
      : "❌ absent (compte sans partie jouée ou pseudo inconnu)");

    if (!existing) {
      if (!authUser) {
        console.log("[sync] Startup sans authUser : élève introuvable → reset local");
        unlockPseudo();
      } else {
        console.log("[sync] Nouveau compte sans partie jouée → état vierge conservé");
      }
      return;
    }

    const student = existing;
    const remoteSession = student.session || 1;
    console.log("[sync] Session locale:", localSession, "| session Supabase:", remoteSession);

    // ── Sauvegarder le mapping uid→pseudo (survit aux reset, corrige les anciens comptes) ──
    if (authUser) {
      localStorage.setItem("lm_uid_" + authUser.id, student.pseudo);
      console.log("[sync] Mapping uid→pseudo sauvegardé:", authUser.id.slice(0, 8) + "… →", student.pseudo);
    }

    // ── Synchronisation permanente user_metadata.pseudo ─────────────────────
    // Fire-and-forget : best-effort, ne doit pas bloquer l'affichage du jeu.
    if (authUser && !metaPseudo) {
      console.log("[sync] updateUser fire-and-forget");
      _qClient.auth.updateUser({ data: { pseudo: student.pseudo } }).then(({ error: metaErr }) => {
        if (metaErr) console.warn("[sync] ⚠️ Sync user_metadata échouée:", metaErr.message);
        else console.log("[sync] ✅ user_metadata.pseudo synchronisé →", student.pseudo);
      });
    }

    // Détection de reset prof : session repassée à 1 alors qu'on était plus loin
    if (remoteSession === 1 && localSession !== null && localSession > 1) {
      console.log("[sync] 🗑️ Élève recréé par prof → reset complet");
      unlockPseudo();
      return;
    }

    // ── Hydratation de l'état élève depuis Supabase (source de vérité) ───────
    console.log("[SYNC] hydration success");
    pseudo          = window.normalizePseudo ? window.normalizePseudo(student.pseudo) : student.pseudo;
    xp              = student.xp_total      || 0;
    bestScore       = student.best_score    || 0;
    statBestAvgTime = student.best_avg_time || null;
    statGames       = student.games_played  || 0;
    localSession    = remoteSession;
    console.log("[sync] ✅ État hydraté → pseudo:", pseudo,
      "| XP:", xp, "| bestScore:", bestScore,
      "| games:", statGames, "| session:", localSession);

    localStorage.setItem("currentSession", String(localSession));
    saveGame();
    console.log("[sync] saveGame() OK — localStorage mis à jour");
    renderPseudo();
    updateRankUI();
    renderStats(null);
    updateLevelButtons();
    console.log("[sync] ✅ UI mise à jour");
  } catch(e) {
    console.error("[sync] ❌ Exception:", e);
  }
}
